<?php declare(strict_types=1); ?>
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Konaklamalar</title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:1100px;margin:40px auto;padding:0 20px}.top{display:flex;justify-content:space-between;align-items:center}.btn{background:#176b50;color:white;padding:11px 16px;border-radius:9px;text-decoration:none;border:0;font-weight:700}table{width:100%;border-collapse:collapse;background:white;border-radius:14px;overflow:hidden;margin-top:22px}th,td{text-align:left;padding:14px;border-bottom:1px solid #edf0ed;font-size:14px}th{color:#68736d;background:#fafbfa}.status{font-size:12px;padding:5px 9px;border-radius:20px;background:#eef4ef}a{color:#176b50}</style></head><body><main class="wrap"><div class="top"><div><h1>Konaklamalar</h1><p>İlanlarınızı, fiyatları ve yayın durumlarını yönetin.</p></div><a class="btn" href="/admin/properties/new">+ Yeni konaklama</a></div><table><thead><tr><th>İlan</th><th>Konum</th><th>Kapasite</th><th>Gecelik</th><th>Durum</th><th></th></tr></thead><tbody><?php foreach($properties as $p): ?><tr><td><strong><?= e($p['title']) ?></strong><br><small><?= e($p['slug']) ?></small></td><td><?= e(trim(($p['district'] ? $p['district'].', ' : '').($p['city'] ?? ''))) ?></td><td><?= (int)$p['max_guests'] ?> kişi</td><td><?= e(number_format((float)$p['base_nightly_price'],0,',','.')) ?> <?= e($p['currency']) ?></td><td><span class="status"><?= e($p['status']) ?></span></td><td><a href="/admin/properties/<?= (int)$p['id'] ?>">Düzenle</a></td></tr><?php endforeach; ?><?php if(!$properties): ?><tr><td colspan="6">Henüz konaklama eklenmemiş.</td></tr><?php endif; ?></tbody></table><p><a href="/admin">← Yönetim paneli</a></p></main></body></html>